const D = { density: .55, energy: .6, speed: 1, scale: 1, turb: .55, bleed: .45, wash: .4, hue: 32, x: .5, y: .5, style: 'sumi', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v,a,b)=> v<a?a:v>b?b:v;
const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };

// --- persistent wash buffer (half-canvas feedback), size-keyed ---
const BW = Math.min(720, Math.max(160, Math.round(width/2)));
const BH = Math.max(2, Math.round(BW*height/width));
const bu = Math.min(BW,BH);
if (!S.ink || S.bw!==BW || S.bh!==BH){
  if (S.ink && S.ink.remove) S.ink.remove();
  S.ink = createGraphics(BW,BH); S.ink.pixelDensity(1);
  S.ink.colorMode(HSB,360,100,100,100);
  S.styleUsed = null; S.seedUsed = null;
  S.ag = []; S.spawnN = 0;
}
const g = S.ink;

// --- ground palette per style ---
const ST = P.style;
let gh,gs,gb, add=false, bleedOn=true, lightGround=false;
if (ST==='jewel-ink'){ gh=232; gs=48; gb=8; add=true; }
else if (ST==='gold-leaf'){ gh=32; gs=52; gb=7; add=true; }
else if (ST==='neon-brush'){ gh=266; gs=34; gb=5; add=true; }
else if (ST==='blueprint'){ gh=212; gs=66; gb=25; add=false; bleedOn=false; }
else { gh=34; gs=22; gb=75; add=false; lightGround=true; } // sumi

// repaint ground on first run / style / seed change (also re-seeds agents)
if (S.styleUsed!==ST || S.seedUsed!==sd){
  S.styleUsed=ST; S.seedUsed=sd; S.ag=[]; S.spawnN=0;
  g.push(); g.blendMode(BLEND); g.noStroke(); g.fill(gh,gs,gb,100); g.rect(0,0,BW,BH); g.pop();
}

// --- curl-noise flow field (divergence-free), drifts on K.t (never re-phases) ---
const zt   = K.t*(0.05 + P.speed*0.06) + sd*0.13;
const fscl = 1.1 + 2.4/clp(P.scale,0.3,3);
const turb = (0.55 + P.turb*2.0 + A.lowmid*1.2) * (1 + 0.14*Math.sin(K.section*0.9));
const eps  = 0.004;
const ns   = (fx,fy)=> noise(fx*fscl + sd*0.7, fy*fscl + 11.3, zt);
const ang  = (fx,fy)=> Math.atan2( ns(fx,fy+eps)-ns(fx,fy-eps), -(ns(fx+eps,fy)-ns(fx-eps,fy)) ) * turb;

// --- brush-agent pool (continuous writing = motion floor) ---
if (!S.ag) { S.ag=[]; S.spawnN=0; }
function spawn(){
  const n = S.spawnN++;
  const spread = 0.26 + 0.24*(0.5+0.5*Math.sin(K.section*0.7));
  const x = clp(clp(P.x,0,1) + (fr(n*3+1)*2-1)*spread, 0.02, 0.98) * BW;
  const y = clp(clp(P.y,0,1) + (fr(n*3+2)*2-1)*spread, 0.02, 0.98) * BH;
  return { x, y, px:x, py:y, age:0, life: 34 + fr(n*3+3)*72,
           bw: bu*(0.010 + fr(n*3+7)*0.028), wp:0, hh: fr(n*5+4), wob: fr(n*5+9)*99 };
}
const target = Math.round(14 + P.density*104);
while (S.ag.length < target) S.ag.push(spawn());
if (S.ag.length > target) S.ag.length = target;

// --- fade the buffer toward ground (ink washes away) ---
const washA = (lightGround ? (1.4 + P.wash*8.5) : (1.8 + P.wash*7.0)) * (0.85 + 0.25*Math.sin(K.section*0.5));
g.push();
g.blendMode(BLEND); g.noStroke();
g.fill(gh,gs,gb,washA); g.rect(0,0,BW,BH);

// --- advance agents + lay tapered variable-width strokes ---
g.blendMode(add ? ADD : BLEND);
const briMul = 0.82 + K.intensity*0.34 + A.rms*0.5;
const kick = K.pulse*0.42 + A.bass*0.6;
const st = bu*0.006*(0.5 + P.speed);
const hueShift = K.section*13 + K.t*2.5;
const eW = 0.35 + P.energy;
for (let k=0;k<S.ag.length;k++){
  const p = S.ag[k];
  const fx = p.x/BW, fy = p.y/BH;
  const a = ang(fx,fy);
  const nx = p.x + Math.cos(a)*st, ny = p.y + Math.sin(a)*st;
  const t = p.age/p.life;
  const env = Math.sin(Math.PI*clp(t,0,1));
  const pr = 0.45 + 0.55*noise(p.wob + p.age*0.05);
  let w = p.bw * env * pr * eW * (1 + kick*0.5);
  if (ST==='blueprint') w *= 0.42;
  const w2 = w*0.5, wp2 = p.wp*0.5;
  const perpx = -Math.sin(a), perpy = Math.cos(a);
  // hue/tone per style
  let ch,cs,cb,ca, hh,hs,hb,ha;
  if (ST==='jewel-ink'){ ch=(P.hue + p.hh*300 + hueShift)%360; cs=82; cb=88*briMul; ca=52+P.energy*28; hh=ch; hs=68; hb=42*briMul; ha=8+P.bleed*20; }
  else if (ST==='gold-leaf'){ ch=(40 + env*10)%360; cs=48+env*32; cb=(58+env*40)*briMul; ca=50+P.energy*30; hh=38; hs=62; hb=30*briMul; ha=7+P.bleed*18; }
  else if (ST==='neon-brush'){ ch=(P.hue + p.hh*210 + hueShift)%360; cs=92; cb=100; ca=48+P.energy*30; hh=ch; hs=80; hb=48; ha=10+P.bleed*26; }
  else if (ST==='blueprint'){ ch=(P.hue*0.1+200)%360; cs=10; cb=96; ca=46+P.energy*30; hh=0; hs=0; hb=0; ha=0; }
  else { // sumi: dark sepia ink, occasional indigo, soft wet halo
    const indigo = p.hh<0.16; ch = indigo?222:(28+p.hh*10); cs = indigo?38:34; cb = 8+p.hh*7; ca=58+P.energy*26;
    hh=ch; hs=indigo?22:16; hb=44; ha=6+P.bleed*20;
  }
  // wet bleed halo (soft wide edge), then core
  if (bleedOn && ha>0){
    const hw = (w + p.wp)*0.5 * (1 + P.bleed*2.3) + 0.6;
    g.noStroke(); g.fill(hh,hs,hb,ha);
    g.quad(p.px+perpx*hw, p.py+perpy*hw, p.px-perpx*hw, p.py-perpy*hw, nx-perpx*hw, ny-perpy*hw, nx+perpx*hw, ny+perpy*hw);
  }
  g.noStroke(); g.fill(ch,cs,cb,ca);
  if (w2+wp2 < 0.35){ g.circle(nx,ny,Math.max(0.8,w)); }
  else { g.quad(p.px+perpx*wp2, p.py+perpy*wp2, p.px-perpx*wp2, p.py-perpy*wp2, nx-perpx*w2, ny-perpy*w2, nx+perpx*w2, ny+perpy*w2); }
  // advance / respawn
  p.px=p.x; p.py=p.y; p.x=nx; p.y=ny; p.wp=w; p.age++;
  if (p.age>=p.life || nx<-6||nx>BW+6||ny<-6||ny>BH+6){ S.ag[k]=spawn(); }
}
g.blendMode(BLEND);
g.pop();

// --- composite to full frame ---
push();
if (P.alpha < 100) tint(0,0,100,P.alpha);
image(g, 0,0, width,height);
pop();

// --- audio treble sparkle on top (partial, never full-frame; zero-safe baseline) ---
if ((A.treble>0.03 || A.rms>0.04) && P.energy>0.05){
  push(); blendMode(ADD); noStroke();
  const spN = Math.round(A.treble*40*P.density);
  for (let i=0;i<spN;i++){
    const r = fr(i*7 + Math.floor(K.beat));
    const sx = (clp(P.x,0,1)+(fr(i*7+2)*2-1)*0.4)*width;
    const sy = (clp(P.y,0,1)+(fr(i*7+3)*2-1)*0.4)*height;
    fill((P.hue+hueShift+40)%360, 40, 100, A.treble*55);
    circle(sx,sy, r*bu*0.02*P.energy + 1);
  }
  blendMode(BLEND); pop();
}
